async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Convert Decimal to float before returning the response
    errors = [{"loc": e["loc"], "msg": e["msg"], "type": e["type"], "ctx": {k: float(v) if isinstance(v, Decimal) else v for k, v in e.get("ctx", {}).items()}} for e in exc.errors()]
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
